function digital_card_data():array{
 $defaults=digital_card_defaults();$saved=json_decode(setting('digital_card','{}'),true);return is_array($saved)?array_replace($defaults,array_intersect_key($saved,$defaults)):$defaults;
}
function digital_card_phone(string $value):string{return preg_replace('/\D/','',$value);}
function digital_card_url(string $value):bool{$p=parse_url($value);return is_array($p)&&($p['scheme']??'')==='https'&&!empty($p['host'])&&!isset($p['user'])&&!isset($p['pass'])&&!preg_match('/[\x00-\x20\x7f]/',$value);}
