function digital_card_save():never{
 if(admin()['role']!=='admin')abort(403,'Owner access required');$data=digital_card_defaults();$data['enabled']=isset($_POST['enabled']);
 try{
  foreach(['name'=>150,'role'=>100,'brand'=>100,'tagline'=>180,'intro'=>700,'closing'=>300,'availability'=>200,'phone_ng_label'=>60,'phone_uk_label'=>60,'phone_ng'=>40,'phone_uk'=>40,'email'=>190,'website'=>500,'whatsapp_message'=>1000,'email_subject'=>190] as $key=>$limit){$value=$_POST[$key]??'';if(!is_string($value)||mb_strlen($value)>$limit||preg_match('/[\x00-\x08\x0b\x0c\x0e-\x1f\x7f]/',$value))throw new InvalidArgumentException('Check the length and content of '.$key.'.');$data[$key]=trim($value);}
  foreach(['name','role','brand','phone_ng','email','website','whatsapp_message'] as $key)if($data[$key]==='')throw new InvalidArgumentException('Please complete '.$key.'.');
  foreach(['name','role','brand','tagline','email_subject'] as $key)if(strpbrk($data[$key],"\r\n")!==false)throw new InvalidArgumentException('Use a single line for '.$key.'.');
  foreach(['phone_ng','phone_uk'] as $key)if($data[$key]!==''&&(!preg_match('/^\+[0-9 ()-]+$/D',$data[$key])||!preg_match('/^[1-9][0-9]{6,14}$/D',digital_card_phone($data[$key]))))throw new InvalidArgumentException('Use international phone numbers, starting with + and country code.');
  if(!filter_var($data['email'],FILTER_VALIDATE_EMAIL)||strpbrk($data['email'],"\r\n")!==false)throw new InvalidArgumentException('Enter a valid business email.');if(!digital_card_url($data['website']))throw new InvalidArgumentException('Website must be a complete HTTPS URL.');
  $submitted=$_POST['socials']??[];if(!is_array($submitted))throw new InvalidArgumentException('Check social links.');
  foreach($data['socials'] as $key=>$_){$value=$submitted[$key]??'';if(!is_string($value)||strlen($value)>500||($value!==''&&!digital_card_url($value)))throw new InvalidArgumentException('Use a complete HTTPS URL for '.$key.'.');$data['socials'][$key]=$value;}
  $services=$_POST['services']??[];if(!is_array($services)||count($services)>10)throw new InvalidArgumentException('Add up to ten service offers.');$data['services']=[];
  foreach($services as $service){if(!is_array($service)||!is_string($service['title']??null)||!is_string($service['description']??null))throw new InvalidArgumentException('Check service titles and descriptions.');$title=trim($service['title']);$description=trim($service['description']);if($title===''&&$description==='')continue;if($title===''||mb_strlen($title)>150||mb_strlen($description)>1500)throw new InvalidArgumentException('Each offer needs a title (up to 150 characters) and a description of up to 1500 characters.');$data['services'][]=['title'=>$title,'description'=>$description];}
  if(!$data['services'])throw new InvalidArgumentException('Include at least one offer.');
  $data['logo']=digital_card_data()['logo'];if(isset($_POST['reset_logo']))$data['logo']=digital_card_defaults()['logo'];$upload=upload_media('logo');if($upload)$data['logo']=$upload;
  sql('INSERT INTO settings(`key`,value) VALUES(?,?) ON DUPLICATE KEY UPDATE value=VALUES(value)',['digital_card',json_encode($data,JSON_THROW_ON_ERROR)]);audit('digital.card.updated');flash('Digital card saved and applied.');
 }catch(Throwable $error){flash($error instanceof InvalidArgumentException||get_class($error)===RuntimeException::class?$error->getMessage():'The card could not be saved. Please try again.','error');}
 go('admin/digital-card');
}
