 admin_page('Owner digital card',function(){ $data=digital_card_data();?><section class="form"><h2>A personal introduction, ready to share.</h2><p>Edit the dedicated card without changing store settings. Empty optional phone/social fields are hidden. The Instagram link initially uses the supplied @thirtysixdegrees handle; confirm it is your intended profile.</p><a class="btn gold" href="/digital-card" target="_blank" rel="noopener">Preview digital card ↗</a><p>Share: <a href="/digital-card"><?=esc(rtrim(cfg()['app_url'],'/').'/digital-card')?></a></p></section>
 <form class="form" method="post" action="/admin/digital-card/save" enctype="multipart/form-data"><?=token()?><label><input type="checkbox" name="enabled" <?=$data['enabled']?'checked':''?>> Publish digital card</label><h2>Identity & logo</h2><img src="<?=esc($data['logo'])?>" alt="Current logo" style="width:200px;max-width:100%;padding:16px;background:#18221c;border-radius:14px"><label>Replace logo (PNG, JPG or WebP, up to 6 MB)<input type="file" name="logo" accept="image/png,image/jpeg,image/webp"></label><label><input type="checkbox" name="reset_logo"> Restore website logo (unless uploading a replacement)</label>
 <?php foreach(['name'=>'Owner name','role'=>'Professional title','brand'=>'Business name','tagline'=>'Brand tagline','intro'=>'Introduction','closing'=>'Closing invitation','availability'=>'Availability / occasions','phone_ng_label'=>'Primary phone label','phone_uk_label'=>'Second phone label','phone_ng'=>'Primary phone / WhatsApp (international format)','phone_uk'=>'Second phone / WhatsApp (optional)','email'=>'Business email','website'=>'Website URL','whatsapp_message'=>'Prefilled WhatsApp message','email_subject'=>'Prefilled email subject'] as $key=>$label):?><label for="dc-<?=$key?>"><?=$label?></label><?php if(in_array($key,['intro','closing','whatsapp_message'])):?><textarea id="dc-<?=$key?>" name="<?=$key?>" rows="3"><?=esc($data[$key])?></textarea><?php else:?><input id="dc-<?=$key?>" name="<?=$key?>" value="<?=esc($data[$key])?>" type="<?=$key==='email'?'email':($key==='website'?'url':'text')?>"><?php endif;endforeach;?>
 <h2>Social profiles</h2><p class="muted">Paste complete https:// profile URLs. Leave unused platforms empty.</p><?php foreach($data['socials'] as $key=>$value):?><label for="social-<?=$key?>"><?=ucfirst($key)?></label><input type="url" id="social-<?=$key?>" name="socials[<?=$key?>]" value="<?=esc($value)?>" placeholder="https://…"><?php endforeach;?><h2>Service offers</h2><p class="muted">Edit, reorder or remove offers. Up to ten can be published.</p><div data-card-services><?php foreach($data['services'] as $i=>$service)digital_card_service_editor($i,$service);?></div><button class="btn" type="button" data-add-service>Add another offer</button><p data-card-editor-status role="status"></p><button class="btn gold">Save digital card</button></form><template id="card-service-template"><?php digital_card_service_editor(999,['title'=>'','description'=>'']);?></template><script src="/public/assets/digital-card-editor-670.js?v=6.7.0" defer></script><?php });
}
function digital_card_service_editor(int $index,array $service):void{?><fieldset data-card-service style="min-width:0;margin:16px 0"><legend>Service offer</legend><label>Title<input name="services[<?=$index?>][title]" maxlength="150" value="<?=esc($service['title'])?>"></label><label>Description<textarea name="services[<?=$index?>][description]" maxlength="1500" rows="3"><?=esc($service['description'])?></textarea></label><button type="button" class="btn" data-service-up aria-label="Move offer up">↑ Up</button> <button type="button" class="btn" data-service-down aria-label="Move offer down">↓ Down</button> <button type="button" class="btn" data-service-remove>Remove offer</button></fieldset><?php }
function digital_card_vcf(array $data):never{
 $escape=static fn(string $v):string=>str_replace(["\\","\r","\n",';',','],["\\\\",'',"\\n","\\;","\\,"],$v);
 $lines=['BEGIN:VCARD','VERSION:3.0','FN:'.$escape($data['name']),'N:;'.$escape($data['name']).';;;','ORG:'.$escape($data['brand']),'TITLE:'.$escape($data['role']),'EMAIL;TYPE=INTERNET,WORK:'.$escape($data['email']),'URL:'.$data['website']];
 foreach(['phone_ng','phone_uk'] as $phone)if($data[$phone]!=='')$lines[]='TEL;TYPE=CELL:+'.digital_card_phone($data[$phone]);
 $lines[]='NOTE:'.$escape($data['tagline']."\n".implode(' · ',array_column($data['services'],'title')));$lines[]='END:VCARD';
 header('Content-Type: text/vcard; charset=utf-8');header('Content-Disposition: attachment; filename="thirtyvi-tosin-contact.vcf"');header('Cache-Control: no-store');
 foreach($lines as $line){$first=true;while(strlen($line)>($first?75:74)){$part=mb_strcut($line,0,$first?75:74,'UTF-8');echo ($first?'':' ').$part."\r\n";$line=substr($line,strlen($part));$first=false;}echo ($first?'':' ').$line."\r\n";}exit;
}
