 $canonical=rtrim(cfg()['app_url'],'/').'/digital-card';header('Cache-Control: no-cache');?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#151b17"><title><?=esc($data['name'].' · '.$data['brand'])?></title><meta name="description" content="<?=esc($data['intro'])?>"><meta property="og:type" content="profile"><meta property="og:title" content="<?=esc($data['name'].' · '.$data['brand'])?>"><meta property="og:description" content="<?=esc($data['intro'])?>"><meta property="og:url" content="<?=esc($canonical)?>"><link rel="canonical" href="<?=esc($canonical)?>"><link rel="stylesheet" href="/public/assets/digital-card-670.css?v=6.7.0"></head><body class="digital-card"><a class="dc-skip" href="#card-main">Skip to card</a><div class="dc-orbit" aria-hidden="true"></div><header class="dc-top"><a href="/">36° <span>THE RESTAURANT</span></a><button type="button" data-card-share><?=digital_card_icon('share')?> Share card</button></header><main id="card-main" class="dc-wrap"><p class="dc-eyebrow dc-entry">GOOD TASTE. PERSONAL CONNECTION.</p><section class="dc-identity dc-entry" aria-labelledby="card-name"><div class="dc-brand"><img src="<?=esc($data['logo'])?>" alt="<?=esc($data['brand'])?> logo"><span><?=esc($data['tagline'])?></span><div class="dc-mark" aria-hidden="true">36°</div></div><div class="dc-person"><span class="dc-eyebrow">A PERSONAL INVITATION</span><h1 id="card-name"><?=esc($data['name'])?></h1><p class="dc-role"><?=esc($data['role'])?> <span>·</span> <?=esc($data['brand'])?></p><p class="dc-intro"><?=nl2br(esc($data['intro']))?></p><div class="dc-main-actions"><a class="dc-button dc-gold" href="https://wa.me/<?=digital_card_phone($data['phone_ng'])?>?text=<?=rawurlencode($data['whatsapp_message'])?>" target="_blank" rel="noopener noreferrer"><?=digital_card_icon('whatsapp')?> Let’s talk</a><a class="dc-button" href="/digital-card/contact.vcf"><?=digital_card_icon('save')?> Save contact</a></div><p class="dc-availability"><i aria-hidden="true"></i><?=esc($data['availability'])?></p></div></section>
 <section class="dc-connect dc-entry" aria-labelledby="connect-title"><div class="dc-section-heading"><span class="dc-eyebrow">ONE TAP AWAY</span><h2 id="connect-title">Make a connection.</h2></div><div class="dc-contact-grid"><?php foreach(['phone_ng'=>'Nigeria','phone_uk'=>'United Kingdom'] as $key=>$label):if($data[$key]==='')continue;?><article class="dc-contact"><span class="dc-contact-icon"><?=digital_card_icon('phone')?></span><div><small><?=esc($data[$key.'_label'])?></small><a class="dc-contact-value" href="tel:+<?=digital_card_phone($data[$key])?>"><?=esc($data[$key])?></a><div class="dc-contact-links"><a href="tel:+<?=digital_card_phone($data[$key])?>">Call <?=digital_card_icon('arrow')?></a><a href="https://wa.me/<?=digital_card_phone($data[$key])?>?text=<?=rawurlencode($data['whatsapp_message'])?>" target="_blank" rel="noopener noreferrer">WhatsApp <?=digital_card_icon('arrow')?></a></div></div></article><?php endforeach;?><article class="dc-contact"><span class="dc-contact-icon"><?=digital_card_icon('email')?></span><div><small>A NOTE TO THE CHEF</small><a class="dc-contact-value dc-email" href="mailto:<?=esc($data['email'])?>?subject=<?=rawurlencode($data['email_subject'])?>"><?=esc($data['email'])?></a><span class="dc-contact-hint">Discuss your next occasion <?=digital_card_icon('arrow')?></span></div></article></div><div class="dc-social-row"><p>Follow the flavour.</p><nav aria-label="Social profiles"><?php foreach($data['socials'] as $key=>$url):if(!$url)continue;?><a href="<?=esc($url)?>" target="_blank" rel="noopener noreferrer" aria-label="<?=esc(ucfirst($key))?> profile" title="<?=esc(ucfirst($key))?>"><?=digital_card_icon($key)?><span><?=esc(ucfirst($key))?></span></a><?php endforeach;?></nav></div></section>
 <section class="dc-offers dc-entry" aria-labelledby="offers-title"><div class="dc-section-heading"><span class="dc-eyebrow">THOUGHTFULLY CURATED</span><h2 id="offers-title">More than a meal.<br> <em>An experience.</em></h2><p>Explore what we can create together.</p></div><div class="dc-services"><?php foreach($data['services'] as $i=>$service):?><details class="dc-service" <?=$i===0?'open':''?>><summary><span class="dc-service-number"><?=str_pad((string)($i+1),2,'0',STR_PAD_LEFT)?></span><h3><?=esc($service['title'])?></h3><span class="dc-service-toggle" aria-hidden="true">+</span></summary><div class="dc-service-body"><p><?=nl2br(esc($service['description']))?></p><a href="https://wa.me/<?=digital_card_phone($data['phone_ng'])?>?text=<?=rawurlencode($data['whatsapp_message']."\n\nI’m interested in ".$service['title'].'.')?>" target="_blank" rel="noopener noreferrer">Enquire about this service <?=digital_card_icon('arrow')?></a></div></details><?php endforeach;?></div></section><section class="dc-closing dc-entry"><span class="dc-eyebrow">THE NEXT OCCASION STARTS HERE</span><h2><?=esc($data['closing'])?></h2><a class="dc-button dc-gold" href="<?=esc($data['website'])?>"><?=digital_card_icon('web')?> Explore <?=esc($data['brand'])?> <?=digital_card_icon('arrow')?></a></section><p class="dc-share-status" role="status" aria-live="polite" data-card-status></p></main><footer class="dc-footer"><span><?=esc($data['brand'])?> · <?=date('Y')?></span><button type="button" data-card-share><?=digital_card_icon('share')?> Share this connection</button></footer><script src="/public/assets/digital-card-670.js?v=6.7.0" defer></script></body></html><?php exit;
